import { HttpErrorResponse } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { interrogator } from '../../model/interrogator';
import { user } from '../../model/user';
import { UserService } from '../../services/user.service';

@Component({
  selector: 'app-profil',
  templateUrl: './profil.component.html',
  styleUrls: ['./profil.component.scss']
})
export class ProfilComponent implements OnInit {

  constructor(private userservice: UserService, private router: Router) { }
  loginuser: any
  ngOnInit(): void {
    this.loginuser = localStorage.getItem('current_user_id');
    this.get_user(this.loginuser);
    this.get_interrogator(this.loginuser);

}



  interrogator: interrogator;
  user: user;

  get_interrogator(loginuser: string) {
    this.userservice.get_interrogator(loginuser).subscribe(
      data => {
        this.interrogator = data;
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');

        }
      }
    )
  }

  get_user(loginuser: string) {
    this.userservice.get_user(loginuser).subscribe(
      data => {
        this.user = data;
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');

        }
      }
    )
  }
  
  change = false;
  mdp = ""
  alertsDismiss: any = [];
  wrong(): void {
    this.alertsDismiss.push({
      type: 'danger',
      msg: `wrong password`,
      timeout: 3000
    });
  }


  alertsDismiss1: any = [];
  change_success(msg :string): void {
    this.alertsDismiss1.push({
      type: 'success',
      msg:msg,
      timeout: 5000
    });
  }
  cancel_change() {
    if (this.change == false)
      (<HTMLInputElement>document.getElementById("mdp")).value = "";
    else
      {this.change = false;
        let element: HTMLElement = document.getElementById('confirm_mdp') as HTMLElement;
        element.className = "form-control" ;
        this.confirm_password=true;
      }


  }


  hide() {
    let element: HTMLElement = document.getElementById('close') as HTMLElement;
    element.click();
  }

  open_model() {
    this.cancel_change();
  }
  pass() {
    this.mdp = (<HTMLInputElement>document.getElementById("mdp")).value;
    this.userservice.verif_pass(this.loginuser, this.mdp).subscribe(
      data => {
        if (data == true)
          this.change = true;
        else
          this.wrong();
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');

        }
      }
    )
  }

 


confirm_password=true;
msg_success:any;
 change_password()
{
var new_mdp=(<HTMLInputElement>document.getElementById("new_mdp")).value;
var confirm_mdp=(<HTMLInputElement>document.getElementById("confirm_mdp")).value;
if ( new_mdp != confirm_mdp)
   {this.confirm_password=false;
    let element: HTMLElement = document.getElementById('confirm_mdp') as HTMLElement;
    element.className = element.className + " is-invalid"}
else
{
  this.confirm_password=true;  
  let element: HTMLElement = document.getElementById('confirm_mdp') as HTMLElement;
  element.className = "form-control" 
  this.userservice.change_mdp(this.loginuser, new_mdp).subscribe(
    (response :any)=> {
      this.hide()
    this.change_success(response.result)
    },
    (error: HttpErrorResponse) => {
      if (error.status == 403) {
        localStorage.clear();
        this.userservice.clear();
        this.router.navigateByUrl('/login');

      }
    }
  )
}
}
}
